#!/usr/bin/env node
/**
 * Generate an SVG chart that shows which languages I actually use on GitHub.
 *
 * The chart is computed from the GitHub REST API, so the numbers reflect real
 * code instead of a hand-written list. It is re-generated by the
 * "Update language stats" GitHub Action (see .github/workflows/languages.yml).
 *
 * Usage:
 *   node scripts/generate-languages.js
 *   node scripts/generate-languages.js --user=octocat --out=assets/languages.svg
 *
 * Configuration (environment variables or CLI flags):
 *   GH_USER          GitHub username                  --user
 *   GH_TOKEN         token used for API requests      (also GITHUB_TOKEN)
 *   OUT_FILE         output SVG path                  --out
 *   TOP_LANGS        languages shown before "Other"   --top
 *   SIZE_WEIGHT      weight of the code-size share    --size-weight
 *   COUNT_WEIGHT     weight of the repo-count share   --count-weight
 *   EXCLUDE_LANGS    comma separated, case insensitive --exclude-langs
 *   EXCLUDE_REPOS    comma separated, case insensitive --exclude-repos
 *   INCLUDE_FORKS    "1" to include forks             --include-forks
 *   INCLUDE_PRIVATE  "1" to include private repos     --include-private
 *   INPUT_FILE       render cached repos instead of the API --input
 *
 * INPUT_FILE expects either an array of { "name": "...", "languages": { "Rust": 123 } }
 * objects or an object with a "repos" array of that shape. It is handy for local
 * previews when the unauthenticated GitHub API rate limit is exhausted.
 *
 * No dependencies are required (Node.js 18+ for global fetch).
 */

"use strict";

const fs = require("node:fs/promises");
const path = require("node:path");

const ROOT = path.resolve(__dirname, "..");
const API = "https://api.github.com";

/** A small subset of the colours used by GitHub's Linguist. */
const LANGUAGE_COLOURS = {
  "c": "#555555",
  "c#": "#178600",
  "c++": "#f34b7d",
  "cmake": "#da3434",
  "css": "#563d7c",
  "dart": "#00b4ab",
  "dockerfile": "#384d54",
  "go": "#00add8",
  "haskell": "#5e5086",
  "html": "#e34c26",
  "java": "#b07219",
  "javascript": "#f1e05a",
  "jupyter notebook": "#da5b0b",
  "kotlin": "#a97bff",
  "less": "#1d365d",
  "lua": "#000080",
  "makefile": "#427819",
  "matlab": "#e16737",
  "objective-c": "#438eff",
  "perl": "#0298c3",
  "php": "#4f5d95",
  "powershell": "#012456",
  "python": "#3572a5",
  "r": "#198ce7",
  "ruby": "#701516",
  "rust": "#dea584",
  "scala": "#c22d40",
  "scss": "#c6538c",
  "shell": "#89e051",
  "swift": "#f05138",
  "tex": "#3d6117",
  "typescript": "#3178c6",
  "vue": "#41b883",
  "zig": "#ec915c",
};

const FALLBACK_COLOURS = [
  "#8b5cf6",
  "#22c55e",
  "#ec4899",
  "#3b82f6",
  "#eab308",
  "#ef4444",
  "#14b8a6",
  "#f97316",
  "#06b6d4",
  "#a855f7",
  "#84cc16",
  "#f43f5e",
];

function flag(value) {
  return /^(1|true|yes|on)$/i.test(String(value ?? ""));
}

function list(value) {
  return String(value ?? "")
    .split(",")
    .map((item) => item.trim().toLowerCase())
    .filter(Boolean);
}

function parseArgs(argv) {
  const options = {};
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (!arg.startsWith("--")) continue;
    const [key, inlineValue] = arg.slice(2).split("=", 2);
    const value = inlineValue !== undefined ? inlineValue : argv[i + 1];
    if (inlineValue === undefined && (value === undefined || value.startsWith("--"))) {
      options[key] = true;
    } else {
      options[key] = value;
      if (inlineValue === undefined) i += 1;
    }
  }
  return options;
}

const args = parseArgs(process.argv.slice(2));

const OPTIONS = {
  user: args.user || process.env.GH_USER || "MelodicTechno",
  token: process.env.GH_TOKEN || process.env.GITHUB_TOKEN || "",
  out: path.resolve(ROOT, args.out || process.env.OUT_FILE || "assets/languages.svg"),
  top: Math.max(1, Number(args.top ?? process.env.TOP_LANGS ?? 10)),
  sizeWeight: Number(args["size-weight"] ?? process.env.SIZE_WEIGHT ?? 0.5),
  countWeight: Number(args["count-weight"] ?? process.env.COUNT_WEIGHT ?? 0.5),
  excludeLangs: new Set(
    list(
      args["exclude-langs"] ??
        process.env.EXCLUDE_LANGS ??
        // Markup, build files and vendored styles hide the "real" languages.
        "HTML,CSS,SCSS,Sass,Less,Batchfile,Dockerfile,Makefile,CMake,TeX,Roff",
    ),
  ),
  excludeRepos: new Set(list(args["exclude-repos"] ?? process.env.EXCLUDE_REPOS ?? "")),
  includeForks: flag(args["include-forks"] ?? process.env.INCLUDE_FORKS),
  includePrivate: flag(args["include-private"] ?? process.env.INCLUDE_PRIVATE),
  input: args.input || process.env.INPUT_FILE || "",
};

if (!Number.isFinite(OPTIONS.top)) throw new Error("TOP_LANGS must be a number");
if (!Number.isFinite(OPTIONS.sizeWeight) || OPTIONS.sizeWeight < 0) {
  throw new Error("SIZE_WEIGHT must be a positive number");
}
if (!Number.isFinite(OPTIONS.countWeight) || OPTIONS.countWeight < 0) {
  throw new Error("COUNT_WEIGHT must be a positive number");
}
if (OPTIONS.sizeWeight + OPTIONS.countWeight === 0) {
  throw new Error("SIZE_WEIGHT and COUNT_WEIGHT cannot both be zero");
}

async function github(url) {
  const headers = {
    Accept: "application/vnd.github+json",
    "User-Agent": "melodictechno-language-stats",
    "X-GitHub-Api-Version": "2022-11-28",
  };
  if (OPTIONS.token) headers.Authorization = `Bearer ${OPTIONS.token}`;

  const response = await fetch(url, { headers });
  if (!response.ok) {
    const body = await response.text().catch(() => "");
    throw new Error(`GitHub API ${response.status} (${response.statusText}) for ${url}\n${body}`);
  }
  return response.json();
}

async function listRepos() {
  const repos = [];
  const base = OPTIONS.includePrivate
    ? `${API}/user/repos?affiliation=owner&sort=pushed`
    : `${API}/users/${encodeURIComponent(OPTIONS.user)}/repos?sort=pushed`;

  for (let page = 1; page <= 10; page += 1) {
    const batch = await github(`${base}&per_page=100&page=${page}`);
    repos.push(...batch);
    if (batch.length < 100) break;
  }
  return repos;
}

async function loadReposFromFile(file) {
  const raw = JSON.parse(await fs.readFile(path.resolve(ROOT, file), "utf8"));
  const entries = Array.isArray(raw) ? raw : raw.repos;
  if (!Array.isArray(entries)) {
    throw new Error(`--input must contain an array of repos (or { "repos": [...] }): ${file}`);
  }
  return entries.map((entry) => ({
    name: entry.name || "unknown",
    fork: Boolean(entry.fork),
    languages:
      entry.languages && typeof entry.languages === "object" ? entry.languages : {},
  }));
}

async function mapWithConcurrency(items, limit, worker) {
  const results = new Array(items.length);
  let next = 0;

  async function run() {
    while (next < items.length) {
      const index = next;
      next += 1;
      results[index] = await worker(items[index], index);
    }
  }

  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, run));
  return results;
}

function normalise(value) {
  return String(value).trim().toLowerCase();
}

async function collectLanguages() {
  const repos = (OPTIONS.input ? await loadReposFromFile(OPTIONS.input) : await listRepos()).filter(
    (repo) => {
      if (repo.fork && !OPTIONS.includeForks) return false;
      if (OPTIONS.excludeRepos.has(normalise(repo.name))) return false;
      return true;
    },
  );

  const languagesByRepo = OPTIONS.input
    ? repos.map((repo) => ({ repo, languages: repo.languages }))
    : await mapWithConcurrency(repos, 5, async (repo) => {
        if (!repo.languages_url) return { repo, languages: {} };
        try {
          return { repo, languages: await github(repo.languages_url) };
        } catch (error) {
          console.warn(`! skipping ${repo.name}: ${error.message}`);
          return { repo, languages: {} };
        }
      });

  const totals = new Map();
  let contributingRepos = 0;
  let totalBytes = 0;

  for (const { languages } of languagesByRepo) {
    let contributes = false;
    for (const [language, bytes] of Object.entries(languages)) {
      if (!Number.isFinite(bytes) || bytes <= 0) continue;
      if (OPTIONS.excludeLangs.has(normalise(language))) continue;

      const entry = totals.get(language) || { bytes: 0, repos: 0 };
      entry.bytes += bytes;
      entry.repos += 1;
      totals.set(language, entry);

      totalBytes += bytes;
      contributes = true;
    }
    if (contributes) contributingRepos += 1;
  }

  if (totalBytes === 0 || contributingRepos === 0) {
    throw new Error("No language data found. Check the username, token and EXCLUDE_LANGS.");
  }

  const weightSum = OPTIONS.sizeWeight + OPTIONS.countWeight;
  const languages = [...totals.entries()]
    .map(([name, entry]) => ({
      name,
      bytes: entry.bytes,
      repos: entry.repos,
      sizeShare: entry.bytes / totalBytes,
      countShare: entry.repos / contributingRepos,
    }))
    .map((entry) => ({
      ...entry,
      score:
        ((OPTIONS.sizeWeight * entry.sizeShare + OPTIONS.countWeight * entry.countShare) /
          weightSum) *
        100,
    }))
    .sort((a, b) => b.score - a.score);

  return {
    languages,
    repoCount: repos.length,
    contributingRepos,
    totalBytes,
  };
}

function colourFor(language) {
  const known = LANGUAGE_COLOURS[normalise(language)];
  if (known) return known;
  let hash = 0;
  for (const char of language) hash = (hash * 31 + char.codePointAt(0)) >>> 0;
  return FALLBACK_COLOURS[hash % FALLBACK_COLOURS.length];
}

function escapeXml(value) {
  return String(value).replace(/[<>&"']/g, (char) => {
    switch (char) {
      case "<":
        return "&lt;";
      case ">":
        return "&gt;";
      case "&":
        return "&amp;";
      case '"':
        return "&quot;";
      default:
        return "&apos;";
    }
  });
}

function formatPercent(percent) {
  if (percent > 0 && percent < 0.1) return "<0.1%";
  const rounded = Math.round(percent * 10) / 10;
  return `${Number.isInteger(rounded) ? rounded.toFixed(0) : rounded.toFixed(1)}%`;
}

function formatBytes(bytes) {
  const units = ["B", "KB", "MB", "GB"];
  let value = bytes;
  let unit = 0;
  while (value >= 1000 && unit < units.length - 1) {
    value /= 1000;
    unit += 1;
  }
  return `${value >= 10 || unit === 0 ? Math.round(value) : value.toFixed(1)} ${units[unit]}`;
}

function buildSvg({ languages, repoCount, contributingRepos }) {
  const width = 760;
  const padding = 24;
  const contentWidth = width - padding * 2;

  const top = languages.slice(0, OPTIONS.top);
  const rest = languages.slice(OPTIONS.top);
  if (rest.length > 0) {
    top.push({
      name: "Other",
      bytes: rest.reduce((sum, item) => sum + item.bytes, 0),
      repos: 0,
      score: rest.reduce((sum, item) => sum + item.score, 0),
    });
  }

  const barTop = 74;
  const barHeight = 16;
  const legendTop = barTop + barHeight + 32;
  const rowHeight = 24;
  const columns = 2;
  const rows = Math.ceil(top.length / columns);
  const footer = OPTIONS.excludeLangs.size
    ? `Excluded: ${[...OPTIONS.excludeLangs].join(", ")}`
    : "";
  const height = legendTop + (rows - 1) * rowHeight + 30 + (footer ? 20 : 0);

  const weightLabel =
    OPTIONS.sizeWeight === OPTIONS.countWeight
      ? "code size and repository count"
      : `code size (${Math.round((OPTIONS.sizeWeight / (OPTIONS.sizeWeight + OPTIONS.countWeight)) * 100)}%) and repository count (${Math.round((OPTIONS.countWeight / (OPTIONS.sizeWeight + OPTIONS.countWeight)) * 100)}%)`;

  const segments = [];
  const legend = [];
  let offset = 0;

  top.forEach((language, index) => {
    const colour = language.name === "Other" ? "#8b949e" : colourFor(language.name);
    const segmentWidth = (language.score / 100) * contentWidth;
    const x = padding + offset;
    const suffix =
      language.name === "Other"
        ? `${language.name}: ${formatPercent(language.score)}`
        : `${language.name}: ${formatPercent(language.score)} · ${formatBytes(language.bytes)} in ${language.repos} repo${language.repos === 1 ? "" : "s"}`;

    segments.push(
      `    <rect x="${x.toFixed(2)}" y="${barTop}" width="${Math.max(segmentWidth, 0.5).toFixed(2)}" height="${barHeight}" fill="${colour}"><title>${escapeXml(suffix)}</title></rect>`,
    );
    offset += segmentWidth;

    const column = index % columns;
    const row = Math.floor(index / columns);
    const columnX = padding + column * (contentWidth / columns);
    const baseline = legendTop + row * rowHeight;
    const percentX = columnX + contentWidth / columns - 16;

    legend.push(
      `    <circle cx="${(columnX + 5).toFixed(2)}" cy="${(baseline - 4).toFixed(2)}" r="5" fill="${colour}"/>`,
      `    <text class="label" x="${(columnX + 18).toFixed(2)}" y="${baseline.toFixed(2)}" font-size="13">${escapeXml(language.name)}</text>`,
      `    <text class="muted" x="${percentX.toFixed(2)}" y="${baseline.toFixed(2)}" font-size="12" text-anchor="end">${formatPercent(language.score)}</text>`,
    );
  });

  const subtitle = `Across ${contributingRepos} public repositor${contributingRepos === 1 ? "y" : "ies"} · weighted by ${weightLabel}`;
  const description = top.map((item) => `${item.name} ${formatPercent(item.score)}`).join(", ");

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="lang-title lang-desc">
  <title id="lang-title">Language usage for @${escapeXml(OPTIONS.user)}</title>
  <desc id="lang-desc">${escapeXml(description)}</desc>
  <style>
    text { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif; }
    .title { fill: #1f2328; }
    .label { fill: #1f2328; }
    .muted { fill: #59636e; }
    .footer { fill: #59636e; }
    @media (prefers-color-scheme: dark) {
      .title, .label { fill: #e6edf3; }
      .muted, .footer { fill: #9198a1; }
    }
  </style>
  <g>
    <text class="title" x="${padding}" y="34" font-size="18" font-weight="600">Language usage</text>
    <text class="muted" x="${padding}" y="56" font-size="12">${escapeXml(subtitle)}</text>
    <clipPath id="language-bar">
      <rect x="${padding}" y="${barTop}" width="${contentWidth}" height="${barHeight}" rx="${barHeight / 2}"/>
    </clipPath>
    <g clip-path="url(#language-bar)">
${segments.join("\n")}
    </g>
${legend.join("\n")}
${footer ? `    <text class="footer" x="${padding}" y="${height - 12}" font-size="11">${escapeXml(footer)}</text>` : ""}
  </g>
</svg>
`;
}

async function main() {
  console.log(`Fetching repositories for @${OPTIONS.user}...`);
  const data = await collectLanguages();

  console.log(
    `Found ${data.languages.length} languages in ${data.contributingRepos}/${data.repoCount} repositories (${formatBytes(data.totalBytes)}).`,
  );
  for (const language of data.languages.slice(0, 10)) {
    console.log(`  ${language.name.padEnd(16)} ${formatPercent(language.score).padStart(6)}  (${language.repos} repos)`);
  }

  const svg = buildSvg(data);
  await fs.mkdir(path.dirname(OPTIONS.out), { recursive: true });

  let previous = "";
  try {
    previous = await fs.readFile(OPTIONS.out, "utf8");
  } catch {
    // First run: nothing to compare against.
  }

  if (previous === svg) {
    console.log(`${path.relative(ROOT, OPTIONS.out)} is already up to date.`);
    return;
  }

  await fs.writeFile(OPTIONS.out, svg, "utf8");
  console.log(`Wrote ${path.relative(ROOT, OPTIONS.out)}.`);
}

main().catch((error) => {
  console.error(error.message || error);
  process.exitCode = 1;
});
